// Guarded typegen.
//
// `appkit generate-types` runs DESCRIBE QUERY against the SQL warehouse: it
// needs warehouse auth and is type-only — its output (shared/appkit-types/
// analytics.d.ts) is committed and used directly at build time. On the
// Databricks Apps runtime we therefore SKIP it, so that if the app's service
// principal ever loses warehouse access the build (and thus the app) does not
// go UNAVAILABLE over type generation. serving.d.ts is regenerated by the
// separate `sync` step, so both type files are present without typegen.
// This mirrors the guard in scripts/postinstall.mjs. Locally, generate types
// as usual so editor types stay fresh.
import { execSync } from 'node:child_process';

const onAppsRuntime = Boolean(process.env.DATABRICKS_APP_NAME || process.env.DATABRICKS_APP_PORT);

if (onAppsRuntime) {
  console.log('[typegen] on Apps runtime — skipping; using committed shared/appkit-types/analytics.d.ts.');
  process.exit(0);
}

execSync('appkit generate-types', { stdio: 'inherit' });
